/**
 * When a song came out, from what YouTube writes under it.
 *
 * A YouTube Music track's video carries a description YouTube writes itself:
 *
 *     Provided to YouTube by JVR Music International Ltd.
 *
 *     晴天 · 周杰倫
 *
 *     葉惠美
 *
 *     ℗ JVR MUSIC INTERNATIONAL LTD.
 *
 *     Released on: 2003-07-29
 *
 *     Auto-generated by YouTube.
 *
 * yt-dlp reads the same text for `release_date`, which the server's downloads
 * tag a file with (services/ytdlp.ts, `RELEASE_DATE_ARGS`); a file a device
 * downloaded is tagged from this instead. An upload date is not a release
 * date — 晴天 went up in 2019 — so a plain video, which says neither, gives
 * nothing, and the file goes without a date rather than with a wrong one.
 */
export interface Release {
  /** `YYYY-MM-DD`, when the description says the day. */
  readonly date: string | null
  /** The year: the day's, or the ℗ line's when only that says one. */
  readonly year: number | null
}

const RELEASED_ON = /^Released on:\s*(\d{4})-(\d{2})-(\d{2})\s*$/m
/** A ℗ line's year, read only from text YouTube wrote itself. */
const PHONOGRAM_YEAR = /^℗\s*(\d{4})\b/m
const AUTO_GENERATED = /Auto-generated by YouTube\.\s*$/

export function releaseOf(description: string): Release {
  const day = RELEASED_ON.exec(description)
  if (day) {
    const [, year, month, date] = day
    return { date: `${year}-${month}-${date}`, year: Number(year) }
  }
  if (!AUTO_GENERATED.test(description.trim())) return { date: null, year: null }
  const phonogram = PHONOGRAM_YEAR.exec(description)
  return { date: null, year: phonogram ? Number(phonogram[1]) : null }
}
